197	  /// servers release their ports/pidfiles instead of being orphaned by the OS hangup (issue #7).
198	  /// Calls `completion` once all windows have stopped (or each one's timeout elapses).
199	  func gracefullyStopAllWindows(timeout: TimeInterval, completion: @escaping () -> Void) {
200	    let live = allStores.filter(\.hasLiveRunCommand)
201	    guard !live.isEmpty else {
202	      completion()
203	      return
204	    }
205	    let group = DispatchGroup()
206	    for store in live {
207	      group.enter()
208	      store.gracefullyStopAllRunCommands(timeout: timeout) { group.leave() }
209	    }
210	    group.notify(queue: .main) { completion() }
211	  }
