258	/// shown — so the owning `AppStore` can register and size the window with no visible resize flash
259	/// (issue #70).
260	struct WindowAccessor: NSViewRepresentable {
261	  let onResolve: (NSWindow) -> Void
262	
263	  func makeNSView(context: Context) -> NSView {
264	    WindowResolvingView(onResolve: onResolve)
265	  }
266	
267	  func updateNSView(_ nsView: NSView, context: Context) {}
268	}
269	
270	private final class WindowResolvingView: NSView {
271	  private let onResolve: (NSWindow) -> Void
272	
273	  init(onResolve: @escaping (NSWindow) -> Void) {
274	    self.onResolve = onResolve
275	    super.init(frame: .zero)
276	  }
277	
278	  @available(*, unavailable) required init?(coder: NSCoder) { fatalError("init(coder:) unused") }
279	
280	  override func viewDidMoveToWindow() {
281	    super.viewDidMoveToWindow()
282	    if let window { onResolve(window) }
283	  }
284	}
