/// that store into the environment, exposes it to menu commands via `focusedSceneObject`, and
/// registers the window↔store pair with `WindowRegistry` (issue #70).
struct RootWindow: View {
  let seed: WindowSeed
  @StateObject private var store: AppStore

  init(seed: WindowSeed) {
    self.seed = seed
    let store = AppStore(projectStore: .shared)
    // Capture the current window's size ONCE, at this window's creation, so the new window can be
    // sized to match it before it's shown (issue #70). nil for the launch window.
    store.pendingInitialWindowSize = WindowRegistry.shared.preferredNewWindowSize
    // Only the launch window runs the What's-New auto-check (see RootView), so restored ⌘N windows
    // don't each pop the dialog.
    store.isRestoreWindow = seed.restore
    _store = StateObject(wrappedValue: store)
  }

  var body: some View {
    RootView()
      .environmentObject(store)
      .environmentObject(store.notifications)
      .environmentObject(store.terminals)
      .environmentObject(store.terminals.agentManager)
      .focusedSceneObject(store)
      .frame(minWidth: 900, maxWidth: .infinity, minHeight: 560, maxHeight: .infinity)
      .background(
        WindowAccessor { window in
          WindowRegistry.shared.register(window: window, store: store)
          store.attachWindow(window)
        }
      )
      .task { await store.bootstrap(restore: seed.restore) }
  }
}

/// Installs the app's local key monitor: the shortcuts that are handled *here* rather than as menu
/// items, because they'd clutter the menu (⌘1–9 / ⌥⌘1–9 tab focus), because they have no menu home
/// (⌘` window cycling, ⌃⌘arrows pane focus, ⌥Tab / ⌃Tab quick switching), or because the monitor must
/// beat a competing menu item (⌘W in the quick terminal). A local monitor runs inside
/// `NSApp.sendEvent`, ahead of both menu key-equivalent dispatch and the focused terminal surface, so
/// it is also the only place a shortcut can be claimed *conditionally* — see the ⌥Tab / ⌃Tab branch,
/// which passes the key back to the terminal when there is nothing to switch to.
final class AppDelegate: NSObject, NSApplicationDelegate, UNUserNotificationCenterDelegate {
  private var monitor: Any?
  /// The global ⌘§ show/hide shortcut while enabled, else nil (issue #13). Registered/torn down by
  /// `updateGlobalHotkey()` to follow the `globalHotkey` setting.
  private var showHideHotkey: GlobalHotkey?
  /// The global ⌥§ quick-terminal shortcut while enabled, else nil (issue #39). Registered/torn down
  /// alongside `showHideHotkey` by `updateGlobalHotkey()` under the same `globalHotkey` setting.
  private var quickTerminalHotkey: GlobalHotkey?
  /// The quick terminal (issue #39) — a ~/ shell in its own chrome-less window. One persistent
  /// controller; its window/surface come and go as it's summoned/closed.
  private let quickTerminal = QuickTerminalController()
  /// Retains the `.showQuickTerminal` observer (posted by the toolbar button) for the app's lifetime.
  private var quickTerminalObserver: NSObjectProtocol?
  /// Observes the `globalHotkey` setting so toggling it takes effect immediately.
  private var hotkeyObservation: Task<Void, Never>?
  /// The system menu-bar item (issue #33) — an `NSStatusItem` owned here so a click can branch on the
  /// notification count (open the list, or just focus the app when there's nothing pending). Retained
  /// for the app's lifetime; created in `applicationDidFinishLaunching`.
  private var menuBarController: MenuBarController?
  /// Catches SIGTERM so a signalled quit stops run commands gracefully (issue #7). Retained so the
  /// `DispatchSource` stays alive for the process's lifetime.
  private var sigtermSource: DispatchSourceSignal?

  deinit { hotkeyObservation?.cancel() }

  /// The store a shortcut in the key monitor below may act on: the one owning the window the event is
  /// actually headed for, and only while that window has no command-palette dialog up.

  // navigation.
  terminals.onSurfaceFocused = { [weak self] targetID in
    self?.focusWorkroomMemberFromSurface(targetID)
  }
  // Hydrate the (global) inspector section layout once at launch — it's shared across all
  // workrooms, so it's loaded here rather than re-loaded on every selection change (issue #24).
  loadInspectorState()
}

/// The last persisted window frame (issue #70), or nil when unset/degenerate.
private static func savedMainWindowFrame() -> NSRect? {
  let string = Defaults[.mainWindowFrame]
  guard !string.isEmpty else { return nil }
  let frame = NSRectFromString(string)
  return (frame.width > 200 && frame.height > 200) ? frame : nil
}

/// Bind this store to its host `NSWindow` once the view tree resolves it (issue #70). Idempotent —
/// `WindowAccessor` may resolve the same window more than once.
func attachWindow(_ window: NSWindow) {
  hostWindow = window
  // Keep the title out of the title bar (issue #70). The title we give the window (selected
  // project/workroom, via `navigationTitle` → `windowTitle`) exists only to name it in the Window
  // menu + Mission Control — never to show in the bar. But a non-empty `navigationTitle` re-asserts
  // `titleVisibility = .visible` on every SwiftUI update, and WindowBackgroundThemer's in-update
  // re-hide can lose that race. So set it hidden here (pre-display, killing the open-time flash) and
  // re-hide after every window update cycle: `didUpdate` fires *after* SwiftUI's changes, so this
  // lock always wins. The guard makes the re-hide a no-op once hidden, so it can't loop.
  window.titleVisibility = .hidden
  // Same race, same lock for the window toolbar: `NavigationSplitView` (RootView) auto-injects a
  // sidebar-toggle toolbar item even with the sidebar column forced `.detailOnly`, and SwiftUI owns
  // + re-shows the toolbar on its update cycles (so `.toolbar(removing: .sidebarToggle)` is a no-op).
  // That lone item renders as a stray `»` "more toolbar items" overflow in the title bar AND keeps
  // SwiftUI's `AppKitToolbarItem.updateMenuFormRepresentation` alive — the layout-driven recompute
  // that stacks into the ≥2s macOS-26 AppHangs (see WindowBackgroundThemer). Hiding the toolbar
  // detaches those item views so neither happens; the taller title bar comes from the `.left`
  // accessory, not the toolbar. Re-hide after every update cycle, guarded so it can't loop.
  window.toolbar?.isVisible = false
  if titleVisibilityObserver == nil {
    titleVisibilityObserver = NotificationCenter.default.addObserver(
      forName: NSWindow.didUpdateNotification, object: window, queue: .main
    ) { [weak window] _ in
      MainActor.assumeIsolated {
        if window?.titleVisibility != .hidden { window?.titleVisibility = .hidden }
        if window?.toolbar?.isVisible == true { window?.toolbar?.isVisible = false }
      }
    }
  }
  // Launch with a single window (issue #70): SwiftUI would otherwise persist + restore every window
  // that was open at quit. We restore the one window's size ourselves (below), so opt out of
  // AppKit's per-window state restoration; extra windows are deliberately not reopened.
  window.isRestorable = false
